<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api/admin';const orders=ref<any[]>([]),channels=ref<any[]>([]),rules=ref<any[]>([]),records=ref<any[]>([]),visible=ref(false),selected=ref<any>();const form=reactive<any>({channelId:null,ruleId:null,promotionApplied:false,channelSubsidy:null,joincomSubsidy:null});const recordOrderIds=computed(()=>new Set(records.value.map(r=>r.orderId)));async function load(){try{[orders.value,channels.value,rules.value,records.value]=await Promise.all([api.orders(),api.channels(),api.rules(),api.records()])as any}catch(e:any){ElMessage.error(e.message)}}function open(row:any){selected.value=row;Object.assign(form,{channelId:null,ruleId:null,promotionApplied:false,channelSubsidy:null,joincomSubsidy:null});visible.value=true}async function calculate(){try{await api.calculate({...form,orderId:selected.value.id});ElMessage.success('已按规则生成结算快照');visible.value=false;load()}catch(e:any){ElMessage.error(e.message)}}onMounted(load);</script>
<template><div class="page"><div class="page-heading"><div><h1>渠道订单</h1><p>仅已激活且完成甲方对账的订单可以生成二级渠道结算。</p></div></div><div class="table-card"><el-table :data="orders"><el-table-column prop="orderNo" label="内部订单号" min-width="185"/><el-table-column prop="umallOrderNo" label="UMALL订单号" min-width="150"/><el-table-column prop="customerName" label="客户" width="110"/><el-table-column prop="planName" label="套餐" min-width="180"/><el-table-column prop="monthlyFee" label="月费" width="90"/><el-table-column prop="activationStatus" label="激活状态" width="110"/><el-table-column prop="reconciliationStatus" label="对账状态" width="110"/><el-table-column label="结算记录" width="110"><template #default="s"><el-tag :type="recordOrderIds.has(s.row.id)?'success':'info'">{{recordOrderIds.has(s.row.id)?'已生成':'未生成'}}</el-tag></template></el-table-column><el-table-column label="操作" fixed="right" width="130"><template #default="s"><el-button link type="primary" :disabled="recordOrderIds.has(s.row.id)" @click="open(s.row)">生成结算</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" title="生成二级渠道结算" width="620"><div class="hint-box" style="margin-bottom:18px">计算完成后保存规则与金额快照。实际付款仍需在“结算记录”中人工确认。</div><el-form label-position="top"><el-form-item label="二级渠道"><el-select v-model="form.channelId" style="width:100%"><el-option v-for="c in channels.filter(x=>x.status==='ENABLED')" :key="c.id" :label="c.channelName" :value="c.id"/></el-select></el-form-item><el-form-item label="结算规则"><el-select v-model="form.ruleId" style="width:100%"><el-option v-for="r in rules.filter(x=>x.enabled)" :key="r.id" :label="`${r.ruleName} · HK$${r.monthlyFee}`" :value="r.id"/></el-select></el-form-item><el-form-item label="推广来源"><el-switch v-model="form.promotionApplied" active-text="计入推广佣金"/></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="渠道承担补贴（留空用规则默认值）"><el-input-number v-model="form.channelSubsidy" :precision="2" :min="0" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="JOINCOM承担补贴"><el-input-number v-model="form.joincomSubsidy" :precision="2" :min="0" style="width:100%"/></el-form-item></el-col></el-row></el-form><template #footer><div class="dialog-footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="calculate">计算并生成</el-button></div></template></el-dialog></div></template>

